# Every game owns one cancellable timer; old callbacks cannot restart a reset game.
def game_pause(app):
    app.running = False
    app.generation += 1
    if app.timer is not None:
        app.root.after_cancel(app.timer)
        app.timer = None

def game_tick(app, generation):
    if not app.running or generation != app.generation:
        return
    app.timer = None
    game_step(app)
    game_draw(app)
    if app.running and generation == app.generation:
        app.timer = app.root.after(60, lambda: game_tick(app, generation))

def game_start(app):
    if app.running or app.over:
        return
    app.running = True
    app.generation += 1
    app.Board.focus_set()
    game_tick(app, app.generation)

def game_close(app):
    game_pause(app)
    app.root.destroy()

# A real, small 3-6-1 neural network learns a synthetic steering teacher.
import math
import random

def neural_create(seed=11):
    rng = random.Random(seed)
    return [[[rng.uniform(-0.3,0.3) for _ in range(4)] for _ in range(6)], [rng.uniform(-0.3,0.3) for _ in range(7)]]

def neural_forward(net, inputs):
    hidden = [math.tanh(sum(w*x for w,x in zip(row,inputs))+row[3]) for row in net[0]]
    output = math.tanh(sum(w*h for w,h in zip(net[1],hidden))+net[1][6])
    return hidden,output

def neural_target(inputs):
    return math.tanh(-1.7*inputs[0]+0.65*inputs[1]+0.35*inputs[2])

def neural_train(net, epochs=12):
    rng = random.Random(23)
    samples = [[rng.uniform(-1,1) for _ in range(3)] for _ in range(220)]
    for _ in range(epochs):
        for inputs in samples:
            hidden,out = neural_forward(net,inputs); delta = (out-neural_target(inputs))*(1-out*out)
            old = net[1][:]
            for i in range(6):
                net[1][i] -= 0.025*delta*hidden[i]
                gradient = delta*old[i]*(1-hidden[i]*hidden[i])
                for j in range(3):
                    net[0][i][j] -= 0.025*gradient*inputs[j]
                net[0][i][3] -= 0.025*gradient
            net[1][6] -= 0.025*delta
    return sum((neural_forward(net,x)[1]-neural_target(x))**2 for x in samples)/len(samples)

def road_center(distance):
    return 300+105*math.sin(distance/160)

def game_reset(app):
    game_pause(app)
    if not hasattr(app,'network'):
        app.network = neural_create()
    app.distance = 0; app.car = road_center(0); app.over = False
    game_draw(app)

def driving_train(app):
    game_pause(app)
    loss = neural_train(app.network)
    app.Status.configure(text=f'Trained 3-6-1 network | Mean squared error: {loss:.5f}. Press Start.')

def game_step(app):
    center = road_center(app.distance)
    inputs = [(app.car-center)/90,(road_center(app.distance+24)-center)/18,math.cos(app.distance/160)]
    _,steering = neural_forward(app.network,inputs)
    app.car += steering*7
    app.distance += 4
    app.over = abs(app.car-road_center(app.distance)) > 83
    if app.over:
        game_pause(app)

def game_draw(app):
    c = app.Board; c.delete('all')
    for y in range(0,540,12):
        center = road_center(app.distance+(440-y)*0.7)
        c.create_rectangle(center-100,y,center+100,y+12,fill='#425168',outline='')
        c.create_line(center,y,center,y+6,fill='white')
    c.create_rectangle(app.car-12,415,app.car+12,450,fill='#ffca55')
    app.Status.configure(text=f'Distance: {app.distance} | '+('Off road. Reset and train.' if app.over else 'Train then Start: synthetic supervised steering, no external packages.'))
